#include "FEMenu_source_shared.h"

#define NEW new

enum { FEMENU_WRAP = 0x002, FEMENU_DONT_SHOW_DISABLED = 0x400 };

enum {
    GT_MENU_OPTIONS = 0,
    GT_MENU_TRICKBOOK = 7,
    GT_MENU_RETRY = 11,
    GT_MENU_CONTINUE = 17,
    GT_MENU_NEXT_TIP = 18,
    GT_MENU_END_RUN = 26,
    GT_FE_MENU_RETURN_FE = 288
};

extern stringx ksGlobalTextArray[];

class PauseMenuSystem;

class TutorialPauseMenuClass : public FEMenu
{
public:
    enum
    {
        NextTip,
        Continue,
        Retry,
        Options,
        TrickBook,
        EndRun,
        ReturnToFE,
    };
    PauseMenuSystem* sys;
    FEMenuEntry *options;
    FEMenuEntry *trickbook;

public:
    TutorialPauseMenuClass(FEMenuSystem* m, int x, int y, color32 c, color32 ch, color32 cha);
    virtual void OnActivate(void);
    virtual void Select(int entry_index);
    virtual void OnButtonRelease(int c, int b);
    virtual void OnDown(int c);
    virtual void OnUp(int c);
    virtual void OnStart(int c);
};

TutorialPauseMenuClass::TutorialPauseMenuClass(FEMenuSystem* m, int x, int y, color32 c, color32 ch, color32 cha)
{
	FEMenu::cons(m, x, y, c, ch, cha);
	sys = (PauseMenuSystem*) m;

	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_NEXT_TIP], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_CONTINUE], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_RETRY], this));
	options = NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_OPTIONS], this);
	Add(options);
	trickbook = NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_TRICKBOOK], this);
	Add(trickbook);
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_MENU_END_RUN], this));
	Add(NEW FEMenuEntry(ksGlobalTextArray[GT_FE_MENU_RETURN_FE], this));

	scale_high = 1.0f;
	flags |= FEMENU_WRAP | FEMENU_DONT_SHOW_DISABLED;
}
